#!/usr/bin/env python3
"""Modernized climate data analysis (Python 3).

Replacement for the legacy Python 2.7 script
``climate_analyzer/analyze_climate.py``. Loads station temperature
data from the sample CSV and prints the mean temperature per station.
"""

from __future__ import annotations

import configparser
from pathlib import Path

import pandas as pd

BASE_DIR = Path(__file__).resolve().parent
DATA_PATH = BASE_DIR / "climate_analyzer" / "sample_data" / "climate_data.csv"
CONFIG_PATH = BASE_DIR / "climate_analyzer" / "config.ini"


class ClimateAnalyzer:
    def __init__(self, config_path: Path = CONFIG_PATH) -> None:
        self.config = configparser.ConfigParser()
        # UTF-8: the config contains non-ASCII values (password, output path)
        self.config.read(config_path, encoding="utf-8")

    def load_temperature_data(self, csv_path: Path = DATA_PATH) -> pd.DataFrame:
        """Load the climate CSV with explicit UTF-8 encoding."""
        if not csv_path.exists():
            raise FileNotFoundError(f"Climate data file not found: {csv_path}")
        return pd.read_csv(csv_path, encoding="utf-8", parse_dates=["date"])

    def station_mean_temperatures(self, data: pd.DataFrame) -> pd.Series:
        """Return the mean temperature per station, ordered by station id."""
        return data.groupby("station_id")["temperature"].mean().sort_index()

    def run_analysis(self) -> None:
        data = self.load_temperature_data()
        for station_id, mean_temp in self.station_mean_temperatures(data).items():
            print(f"Station {station_id} mean temperature: {mean_temp:.1f}°C")


if __name__ == "__main__":
    analyzer = ClimateAnalyzer()
    analyzer.run_analysis()

